*{box-sizing:border-box} :root{color-scheme:dark;--ink:#f3f5e8;--muted:#a9b29b;--green:#d5ee74;--orange:#ffc37b;--mono:'DM Mono',monospace;--display:'Outfit',sans-serif} html,body{margin:0;min-height:100%;background:#101612;color:var(--ink);font-family:var(--display)} body{min-height:100svh;display:grid;place-items:center;padding:22px;background:radial-gradient(ellipse at 50% 0%,#28382a 0,#141e18 48%,#101612 100%);overflow-x:hidden}.game-shell{width:min(1120px,100%);margin:auto}.topbar{height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 6px 12px}.brand{display:flex;align-items:center;gap:10px;color:var(--ink);font-size:15px;letter-spacing:.13em;font-weight:800;text-decoration:none}.brand-mark{display:grid;place-items:center;width:25px;height:25px;border:1px solid #718351;border-radius:50%;color:var(--green);font-size:17px}.brand-tag,.top-status,.sound-state,.hud-label,.footer-meta,.eyebrow,.briefing-item b,.briefing-item span,.overlay-foot{font-family:var(--mono);letter-spacing:.06em}.brand-tag{font-size:9px;color:#8f9b88;border-left:1px solid #4d5948;margin-left:4px;padding-left:13px;font-weight:400}.top-status{font-size:10px;color:#aab69d;display:flex;align-items:center;gap:9px}.live-dot{height:7px;width:7px;border-radius:50%;background:#c9eb73;box-shadow:0 0 12px #c9eb73}.icon-button{border:1px solid #465445;background:#1a241d;border-radius:9px;color:#d9e8c1;padding:7px 10px;font-size:15px;cursor:pointer}.sound-state{font-size:8px;margin-left:7px;color:#aeba99}.game-frame{position:relative;width:100%;aspect-ratio:8/5;overflow:hidden;border:1px solid #53634b;border-radius:17px;background:#233b28;box-shadow:0 26px 90px #0009,0 0 0 5px #a4ca6020;isolation:isolate}.game-frame canvas{display:block;width:100%;height:100%;image-rendering:auto;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 46%,transparent 55%,#111a1790 100%);mix-blend-mode:multiply}.hud{position:absolute;z-index:2;left:22px;right:22px;top:17px;display:grid;grid-template-columns:1fr 1.15fr 1fr;align-items:start;gap:15px;pointer-events:none;text-shadow:0 2px 6px #152316}.hud-label{font-size:9px;color:#f1f5d6;letter-spacing:.12em;margin-bottom:7px}.tiny-heart{color:#ffb48c;margin-left:5px}.health-track{position:relative;height:12px;width:min(192px,100%);background:#14231d9e;border:1px solid #f4f2dc7a;border-radius:8px;overflow:hidden}.health-fill{height:100%;width:100%;background:linear-gradient(90deg,#ff9d73,#f5dc8c);border-radius:8px;transition:width .2s}.health-value{position:absolute;inset:0;text-align:center;line-height:10px;font:8px var(--mono);color:#152218}.hud-center{text-align:center}.stage-name{font-weight:700;font-size:16px;letter-spacing:.07em;color:#fff4d5;text-transform:uppercase;text-shadow:0 2px 8px #1a251c}.stage-progress{height:4px;width:min(220px,100%);margin:7px auto 0;background:#1d302880;border-radius:4px;overflow:hidden}.stage-progress span{display:block;width:0;height:100%;background:#d9ed86;box-shadow:0 0 10px #d9ed86;transition:width .2s}.hud-right{text-align:right}.snack-value{font-size:22px;line-height:1;font-weight:700;color:#fff3bb}.web-meter{height:4px;width:65px;margin:6px 0 0 auto;background:#10221fa0;border-radius:4px;overflow:hidden}.web-meter span{height:100%;display:block;width:100%;background:#c6ebf0;transition:width .15s}.toast{position:absolute;z-index:4;top:92px;left:50%;transform:translate(-50%,-6px);font-size:13px;font-weight:700;letter-spacing:.06em;color:#fff6c8;text-shadow:0 2px 8px #1b291c;text-align:center;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#102118c9,#1021188a 46%,#101d18a8);backdrop-filter:blur(3px);transition:opacity .25s}.overlay.hidden{opacity:0;pointer-events:none}.overlay-card{width:min(510px,90%);padding:24px 28px 17px;border-radius:19px;border:1px solid #d5ef8759;background:linear-gradient(145deg,#293b2dde,#162820ed 74%);box-shadow:0 20px 70px #080f0bc9;text-align:center;transition:transform .25s}.overlay.hidden .overlay-card{transform:translateY(12px)}.eyebrow{display:flex;align-items:center;justify-content:center;gap:10px;font-size:8px;color:#d3e28b;letter-spacing:.14em}.eyebrow-line{height:1px;width:30px;background:#b9d36d70}.title-lockup{display:flex;align-items:center;justify-content:center;gap:13px;margin:9px 0 0}.title-star{width:53px;height:53px;border-radius:50%;display:grid;place-items:center;color:#e0f68b;font-size:35px;background:radial-gradient(circle,#607443,#32462d 70%);box-shadow:0 0 30px #c6eb6b45}.title-lockup h1{margin:0;text-align:left;font-size:47px;line-height:.75;letter-spacing:.04em;font-weight:800}.title-lockup h1 span{color:#d8ed84}.subtitle{font-size:14px;line-height:1.55;color:#d3ddc8;margin:17px 0}.briefing{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:15px 0 17px;text-align:left}.briefing-item{min-height:55px;display:flex;align-items:center;gap:8px;padding:8px;background:#111e19a8;border:1px solid #8293633d;border-radius:9px}.briefing-icon{font-size:20px;color:#d5eb8a}.briefing-item b{display:block;font-size:8px;color:#e6f0cf;margin-bottom:4px}.briefing-item span:not(.briefing-icon){display:block;font-size:7px;color:#a5b49e;white-space:nowrap;letter-spacing:0}.primary-button{display:flex;align-items:center;justify-content:space-between;width:100%;border:0;border-radius:10px;padding:13px 15px;background:#d8ed83;color:#1c2b1d;font:700 12px var(--mono);letter-spacing:.12em;cursor:pointer;transition:transform .15s,background .15s}.primary-button:hover{transform:translateY(-2px);background:#e8f69f}.button-arrow{font-size:18px}.overlay-foot{display:flex;justify-content:space-between;margin-top:12px;color:#8e9d8b;font-size:8px}.overlay-foot b{color:#e4ebd2}.pause-button{position:absolute;z-index:3;right:17px;top:63px;width:31px;height:31px;border:1px solid #f2f0cf8a;border-radius:8px;background:#1c332784;color:white;font-size:14px;cursor:pointer;display:none}.pause-button.visible{display:block}.bottom-bar{height:45px;padding:12px 5px 0;display:flex;justify-content:space-between;align-items:center;color:#9da995}.tip{display:flex;gap:9px;align-items:center;font-size:11px}.tip-icon{color:#d3ec7e}.footer-meta{font-size:8px;display:flex;align-items:center;gap:10px;letter-spacing:.08em}.footer-meta b{color:#e1e9d2;font-weight:500}.footer-meta i{width:3px;height:3px;background:#788771;border-radius:50%}.mobile-controls{display:none}.game-frame:focus{outline:none}
@media(max-width:700px){body{padding:9px;background:#101612}.game-shell{width:100%}.topbar{height:48px;padding:0 3px 9px}.brand{font-size:13px;gap:7px}.brand-tag{font-size:7px;padding-left:8px}.top-status{font-size:8px}.icon-button{padding:5px 8px}.game-frame{border-radius:12px;aspect-ratio:3/2}.hud{left:11px;right:11px;top:10px;gap:8px}.hud-label{font-size:7px;margin-bottom:5px}.health-track{height:10px}.health-value{line-height:8px;font-size:7px}.stage-name{font-size:11px}.stage-progress{margin-top:5px}.snack-value{font-size:17px}.web-meter{width:48px;margin-top:5px}.toast{top:64px;font-size:11px}.pause-button{right:10px;top:48px;width:27px;height:27px}.bottom-bar{height:auto;min-height:38px;align-items:flex-start;gap:5px;flex-direction:column;padding:8px 3px 0}.tip{font-size:10px}.footer-meta{font-size:7px}.overlay-card{padding:16px 17px 12px;width:min(440px,93%)}.eyebrow{font-size:7px}.title-lockup h1{font-size:38px}.title-star{width:45px;height:45px;font-size:30px}.subtitle{font-size:12px;margin:12px 0}.briefing{gap:4px;margin:10px 0}.briefing-item{padding:6px 4px;gap:4px;min-height:46px}.briefing-icon{font-size:15px}.briefing-item b{font-size:7px}.briefing-item span:not(.briefing-icon){font-size:6px}.primary-button{padding:11px;font-size:10px}.overlay-foot{font-size:7px}.mobile-controls{position:absolute;z-index:3;inset:auto 0 10px;height:103px;padding:0 13px;display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none;opacity:.92}.joystick{position:relative;pointer-events:auto;width:92px;height:92px;border-radius:50%;border:1px solid #edf3d264;background:#1320196b;touch-action:none}.joystick:before,.joystick:after{content:'';position:absolute;background:#dfe9ca26}.joystick:before{width:1px;height:100%;left:50%}.joystick:after{height:1px;width:100%;top:50%}.stick{position:absolute;z-index:1;left:26px;top:26px;width:38px;height:38px;border-radius:50%;background:#d6ed8bca;border:1px solid #f4ffd8;box-shadow:0 2px 12px #09110b9c;touch-action:none}.joy-label{position:absolute;left:50%;top:calc(100% + 4px);transform:translateX(-50%);font:7px var(--mono);letter-spacing:.15em;color:#e8efd9;text-shadow:0 1px 5px #000}.touch-actions{pointer-events:auto;display:flex;align-items:flex-end;gap:8px}.touch-actions button{border:1px solid #edf3d27a;background:#19281fc9;color:#eff4df;border-radius:50%;font:8px var(--mono);letter-spacing:.06em;touch-action:none;box-shadow:0 3px 10px #0006}.touch-jump{width:60px;height:60px}.touch-web{width:54px;height:54px;margin-bottom:11px}.touch-web span{display:block;font-size:17px}.mobile-controls button:active{background:#d6ed8b;color:#17221a}.overlay{backdrop-filter:blur(2px)} }
@media(max-height:520px) and (orientation:landscape){body{padding:5px}.topbar{height:34px;padding-bottom:4px}.bottom-bar{height:28px;padding-top:5px}.game-frame{height:min(75vh,600px);width:auto;margin:0 auto;aspect-ratio:8/5}.game-shell{display:flex;flex-direction:column;align-items:center}.topbar,.bottom-bar{width:min(calc(75vh * 1.6),100%)}.mobile-controls{bottom:4px;transform:scale(.8);transform-origin:bottom left}.overlay-card{padding:10px 20px}.title-lockup{margin-top:3px}.subtitle{margin:7px 0}.briefing{margin:7px 0}.primary-button{padding:8px}.overlay-foot{margin-top:7px}}

