function update(dt){
  game.time+=dt;game.totalTime+=dt;if(game.mode!=='play')return;game.stageTime+=dt;
  if(game.toastTimer>0){game.toastTimer-=dt;if(game.toastTimer<=0)ui.toast.classList.remove('show');}
